// index where the next value will be written (ring pointer)
int
m_window;
// regression window length (how many points feed the slope fit)
int
m_lags[];
// lag ladder (in blocks) used to build the structure function
int
m_lagCount;
// number of active lags in m_lags
double
m_lastH;
// most recently computed Hurst estimate
double
m_lastVolOfVol;
// std-dev of the log-vol series over the regression window
